-- Module quizzes: each lesson of a course has its own questions.
--   quiz_lesson_questions   which questions belong to which lesson (a question may sit in lessons of different courses)
--   quiz_questions.module_only   true for questions written for module quizzes: they appear in module quizzes only, not in
--                                the diagnostic, sprint, drill or full mock, so the exam-weighted practice is unchanged
-- The seed (steps 2 to 4) runs only while quiz_lesson_questions is empty, so re-running never restores a question or a
-- lesson membership that an admin has removed. Part 1 is additive and safe to re-run.
-- Generated by scripts/generate-submodule-seed-sql.ts. Needs 0006 to 0012 to have run.

-- 1. Structure
alter table quiz_questions add column if not exists module_only boolean not null default false;

create table if not exists quiz_lesson_questions (
  id           serial primary key,
  topic_id     integer not null references quiz_skilljar_topics(id) on delete cascade,
  question_id  integer not null references quiz_questions(id) on delete cascade,
  unique (topic_id, question_id)
);
create index if not exists quiz_lesson_questions_question_idx on quiz_lesson_questions (question_id);
-- Same as the other quiz tables: the app reads and writes through the server with the service-role key
alter table quiz_lesson_questions enable row level security;

-- 2. New questions for lessons that had none (15 questions, module quiz only)
with nq(track, domain, section, difficulty, question, option_a, option_b, option_c, option_d, answer, explanation, course, lesson) as (values
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Understand and manage context limitations and memory considerations (when to restart, summarize, or persist)$q$, $q$Easy$q$, $q$A user asks Claude the same question in two separate new conversations and receives answers that are worded differently but say the same thing. What best explains this?$q$, $q$Claude generates each response afresh, so the wording can vary from one run to the next even when the meaning is the same$q$, $q$Claude remembers the first conversation and deliberately rewords its answer to avoid repeating itself$q$, $q$One of the two answers must be a malfunction and should be reported$q$, $q$Claude can only give one fixed answer to a question unless it is reset$q$, $q$A$q$, $q$Claude composes each response as it goes, so the exact wording can differ between runs even when the substance matches. That is normal behaviour, not a fault. It is a reason to judge an output by whether it meets your criteria rather than by whether it repeats an earlier phrasing.$q$, $q$Claude Platform & Model Foundations$q$, $q$How Claude Behaves$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Understand and manage context limitations and memory considerations (when to restart, summarize, or persist)$q$, $q$Easy$q$, $q$A colleague opens a brand-new conversation and expects Claude to remember what they discussed yesterday. What should they know?$q$, $q$A new conversation starts without the earlier one unless the information is provided again or kept through a feature designed to persist it, such as a Project$q$, $q$Claude automatically recalls every past conversation and will bring it up on request$q$, $q$Claude remembers earlier chats only when a more expensive model is selected$q$, $q$Claude shares what each person says with every other user, so earlier chats are always available$q$, $q$A$q$, $q$Each new conversation begins with only the context you give it. To carry background forward, restate the key points or keep them somewhere Claude is configured to read, such as a Project's instructions and knowledge. Claude does not pass one user's conversations to other users.$q$, $q$Claude Platform & Model Foundations$q$, $q$How Claude Behaves$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Select appropriate Claude product features (Projects, research mode, chat, artifacts)$q$, $q$Medium$q$, $q$A team member wants Claude to work alongside them on the real files and folders on their computer, for example to organise and update a set of documents. Which entry point is designed for that?$q$, $q$Claude Cowork, which works with a person on their own files and projects$q$, $q$A plain chat conversation in which the user retypes each file's contents by hand$q$, $q$The Claude Developer Platform, which is aimed at building applications rather than everyday file work$q$, $q$A system prompt, which is a setting rather than a place to work$q$, $q$A$q$, $q$Different entry points suit different work. Cowork is built for collaborating on a person's own files and projects. A chat conversation can help with pasted content but is not set up to work on files in place, and the Developer Platform is for building applications.$q$, $q$Claude Platform & Model Foundations$q$, $q$Core Entry Points$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Select appropriate Claude product features (Projects, research mode, chat, artifacts)$q$, $q$Medium$q$, $q$A developer wants Claude to help build, change and run code inside their local project from the terminal. Which entry point fits best?$q$, $q$Claude Code, which works on a codebase directly from the command line$q$, $q$A chat conversation in a browser with the code pasted in each time$q$, $q$An Artifact, which renders a single standalone document$q$, $q$A Project's custom instructions, which store background but cannot run anything$q$, $q$A$q$, $q$Claude Code is the entry point for working on a codebase from the terminal, where it can read the project and run commands. A browser chat, an Artifact or Project instructions can each help with code in some way, but none of them works directly inside the local project.$q$, $q$Claude Platform & Model Foundations$q$, $q$Core Entry Points$q$),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$Follow organizational AI policies and governance standards$q$, $q$Medium$q$, $q$A colleague shares a Skill they found online and suggests everyone add it to their Claude setup. What is the most sensible first step?$q$, $q$Review what the Skill tells Claude to do and which tools or data it can reach, and check it against organisational policy before adding it$q$, $q$Add it straight away, because a Skill only changes how answers are formatted$q$, $q$Roll it out to the whole team at once so everyone benefits together$q$, $q$Ask Claude to confirm that the Skill is safe and rely on that reply$q$, $q$A$q$, $q$A Skill carries instructions and can influence what Claude does with the access it has, so it deserves the same scrutiny as any other software you add. Review it, understand what it can touch, and check it against your policy before anyone relies on it. Claude's own assurance is not a substitute for a review.$q$, $q$Governance, Risk & Responsible Use$q$, $q$Skill Trust & Feature-Level Risk$q$),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$Follow organizational AI policies and governance standards$q$, $q$Hard$q$, $q$A team plans to switch on web search and a connector to a shared drive for a pilot. How should the risk be judged?$q$, $q$Feature by feature: each added capability or connection widens what Claude can see or do, so assess the data and actions each one exposes$q$, $q$Once Claude itself is approved, every feature carries the same risk and needs no further review$q$, $q$By the size of the model alone, since larger models are always riskier$q$, $q$Only for features that cost extra, because free features cannot expose anything$q$, $q$A$q$, $q$Risk comes from what Claude can reach and do, and each feature or connector changes that. Approving the tool in general does not approve every capability. Look at the data a connector exposes and the actions a feature allows, then decide whether to enable it and for whom.$q$, $q$Governance, Risk & Responsible Use$q$, $q$Skill Trust & Feature-Level Risk$q$),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$LLM Fundamentals$q$, $q$Easy$q$, $q$A developer sends an identical prompt twice at the default settings and receives two differently worded but equivalent answers. What does this show?$q$, $q$Output is sampled, so identical inputs can produce different outputs unless sampling is constrained$q$, $q$The first response was cached incorrectly and should be discarded$q$, $q$The model's weights changed between the two requests$q$, $q$The prompt must contain an error that makes the model unstable$q$, $q$A$q$, $q$A language model picks each next token from a probability distribution, so results can vary from run to run. Lowering the sampling randomness makes outputs more consistent, but exact repeatability is not guaranteed, so applications should be built to tolerate variation.$q$, $q$MSO Foundations$q$, $q$How LLMs Behave$q$),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$LLM Fundamentals$q$, $q$Medium$q$, $q$A model states a detailed fact with complete confidence, and the fact turns out to be wrong. Which explanation fits how language models work?$q$, $q$The model produces fluent text from learned patterns and does not look facts up, so a confident tone is not evidence of accuracy$q$, $q$The model always knows when it is wrong and chooses to mislead the user$q$, $q$Confident wording only appears when the underlying fact has been verified$q$, $q$The error shows the request was sent to the wrong model tier$q$, $q$A$q$, $q$Models generate plausible text from patterns learned in training, and they can state incorrect details fluently. Confidence of tone is therefore no guarantee of accuracy, which is why applications that matter should verify important claims against a trusted source.$q$, $q$MSO Foundations$q$, $q$How LLMs Behave$q$),
  ($q$developer$q$, $q$Prompt and Context Engineering$q$, $q$Prompt Engineering$q$, $q$Medium$q$, $q$A team needs Claude to work through a hard, multi-step problem and also handles many simple lookups. How should extended thinking be used?$q$, $q$Enable it with a reasoning budget sized to the difficulty for the hard problems, and leave simple requests without it$q$, $q$Always enable the largest possible budget for every request$q$, $q$Disable it everywhere, because reasoning only adds cost$q$, $q$Raise the temperature to its maximum so the model explores more options$q$, $q$A$q$, $q$Extended thinking lets the model reason before answering, which helps on hard problems but adds latency and cost. Match the budget to the task: give difficult work room to think and keep simple requests fast and cheap. Temperature is a separate sampling control and is not a substitute for reasoning.$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$Extended Thinking$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Software Engineering Foundations$q$, $q$Medium$q$, $q$A team built a working Claude integration for one client and wants another team to reuse it on a different project. Which preparation makes reuse most likely to succeed?$q$, $q$Separate project-specific settings from the code, document setup and configuration, and include tests and examples$q$, $q$Hard-code the first client's settings so the code is ready to run as it is$q$, $q$Share the finished output only, with no documentation, to protect the work$q$, $q$Rely on the original author being available to explain how it works$q$, $q$A$q$, $q$Reuse depends on someone else being able to set the code up and trust it without the author. Keeping settings outside the code, documenting how to configure it, and shipping tests and examples lets another team adapt it safely. Hard-coded values and missing documentation force every user to rediscover how it works.$q$, $q$Accelerators & IP Contribution$q$, $q$Packaging for Reuse$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Software Engineering Foundations$q$, $q$Medium$q$, $q$A developer fixes a bug in an open-source library used in their Claude project and wants the maintainers to accept the fix. What most improves the chance of acceptance?$q$, $q$A small, focused change with a clear description, tests that cover it, and respect for the project's contribution guidelines$q$, $q$Bundling the fix with unrelated refactors so the maintainers get more value at once$q$, $q$Submitting the change with no description, since the code speaks for itself$q$, $q$Asking the maintainers to merge it quickly because the developer has a deadline$q$, $q$A$q$, $q$Maintainers have to review and support whatever they accept. A narrow change that explains what it fixes, comes with tests and follows the project's guidelines is easy to review and low risk to merge. Mixing in unrelated work or leaving out the explanation makes review harder.$q$, $q$Accelerators & IP Contribution$q$, $q$Contributing Back$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Software Engineering Foundations$q$, $q$Hard$q$, $q$A team wants to publish a reusable component it built during a client engagement. What must be checked first?$q$, $q$That the organisation and the client agreements allow the work to be shared, and that it contains no client data or secrets$q$, $q$Only that the code compiles and the tests pass$q$, $q$That the component is large enough to be worth sharing$q$, $q$Nothing, because code written by your own team is always free to publish$q$, $q$A$q$, $q$Who owns the work, and what may be shared, is set by agreements and policy, not by who wrote the code. Check those first, and make sure the component carries no client data, credentials or confidential detail. Passing tests or being useful does not give anyone the right to publish it.$q$, $q$Accelerators & IP Contribution$q$, $q$Contributing Back$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Understanding Requirements$q$, $q$Medium$q$, $q$A team is about to build a Claude-based feature. Which question belongs in requirements gathering?$q$, $q$What does a successful result look like, who will use it, and what limits such as data sensitivity, speed and cost apply?$q$, $q$Which model has the largest context window, whatever the use case?$q$, $q$How soon can it be released before the requirements are agreed?$q$, $q$Which prompt wording looks best in one demonstration?$q$, $q$A$q$, $q$Requirements say what the feature must achieve and under what constraints, so that design and testing have something to be measured against. Picking a model, a release date or a demo prompt before the goal and limits are known risks building the wrong thing.$q$, $q$Accelerators & IP Contribution$q$, $q$Requirements & Lifecycle$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Claude Application Design$q$, $q$Medium$q$, $q$A security team requires Claude usage to stay inside the company's existing cloud provider account and governance. What should the team compare?$q$, $q$Which platforms offer Claude within that provider, and how their features, pricing and data handling measure up against the requirements$q$, $q$Only which platform has the lowest list price per token, ignoring governance$q$, $q$Which platform the team happened to use on an unrelated project last year$q$, $q$Nothing, because every platform exposes identical Claude features at the same time$q$, $q$A$q$, $q$Where Claude runs affects governance, data handling, available features and cost. Start from the requirements, then check what each option offers within the provider you must use. Price alone ignores governance, and platforms do not always offer the same features at the same time.$q$, $q$Accelerators & IP Contribution$q$, $q$Comparing Platforms$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$Claude Application Design$q$, $q$Hard$q$, $q$An integration runs on one platform today and may need to move to another later. Which design choice makes a move easiest?$q$, $q$Keep platform-specific calls behind a thin internal interface and keep configuration outside the code$q$, $q$Spread platform-specific calls throughout the codebase wherever they are needed$q$, $q$Keep prompts only in each platform's console and nowhere else$q$, $q$Avoid tests, so that nothing is tied to a particular platform$q$, $q$A$q$, $q$Isolating the platform-specific parts behind one internal interface, and keeping configuration separate from code, means a move changes a small, known area instead of the whole application. Scattering platform calls or leaving prompts in a console makes every change expensive, and skipping tests only hides the problem.$q$, $q$Accelerators & IP Contribution$q$, $q$Comparing Platforms$q$)
)
insert into quiz_questions (module_id, section, difficulty, question, option_a, option_b, option_c, option_d, answer, explanation, order_index, module_only)
select m.id, nq.section, nq.difficulty, nq.question, nq.option_a, nq.option_b, nq.option_c, nq.option_d, nq.answer, nq.explanation,
       coalesce((select max(x.order_index) from quiz_questions x where x.module_id = m.id), 0)
         + row_number() over (partition by m.id order by nq.question),
       true
from nq
join quiz_modules m on m.title = nq.domain and m.track = nq.track
where not exists (select 1 from quiz_lesson_questions)
  and not exists (select 1 from quiz_questions x where x.module_id = m.id and x.question = nq.question);

-- Give each new question its course and lesson, so the link under its explanation names the lesson
with nq(track, domain, question, course, lesson) as (values
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A user asks Claude the same question in two separate new conversations and receives answers that are worded differently but say the same thing. What best explains this?$q$, $q$Claude Platform & Model Foundations$q$, $q$How Claude Behaves$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A colleague opens a brand-new conversation and expects Claude to remember what they discussed yesterday. What should they know?$q$, $q$Claude Platform & Model Foundations$q$, $q$How Claude Behaves$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A team member wants Claude to work alongside them on the real files and folders on their computer, for example to organise and update a set of documents. Which entry point is designed for that?$q$, $q$Claude Platform & Model Foundations$q$, $q$Core Entry Points$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A developer wants Claude to help build, change and run code inside their local project from the terminal. Which entry point fits best?$q$, $q$Claude Platform & Model Foundations$q$, $q$Core Entry Points$q$),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$A colleague shares a Skill they found online and suggests everyone add it to their Claude setup. What is the most sensible first step?$q$, $q$Governance, Risk & Responsible Use$q$, $q$Skill Trust & Feature-Level Risk$q$),
  ($q$associate$q$, $q$Governance, Risk, and Responsible Use$q$, $q$A team plans to switch on web search and a connector to a shared drive for a pilot. How should the risk be judged?$q$, $q$Governance, Risk & Responsible Use$q$, $q$Skill Trust & Feature-Level Risk$q$),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$A developer sends an identical prompt twice at the default settings and receives two differently worded but equivalent answers. What does this show?$q$, $q$MSO Foundations$q$, $q$How LLMs Behave$q$),
  ($q$developer$q$, $q$Model Selection and Optimization$q$, $q$A model states a detailed fact with complete confidence, and the fact turns out to be wrong. Which explanation fits how language models work?$q$, $q$MSO Foundations$q$, $q$How LLMs Behave$q$),
  ($q$developer$q$, $q$Prompt and Context Engineering$q$, $q$A team needs Claude to work through a hard, multi-step problem and also handles many simple lookups. How should extended thinking be used?$q$, $q$Production-Grade Prompting, Agents & Tool Use$q$, $q$Extended Thinking$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A team built a working Claude integration for one client and wants another team to reuse it on a different project. Which preparation makes reuse most likely to succeed?$q$, $q$Accelerators & IP Contribution$q$, $q$Packaging for Reuse$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A developer fixes a bug in an open-source library used in their Claude project and wants the maintainers to accept the fix. What most improves the chance of acceptance?$q$, $q$Accelerators & IP Contribution$q$, $q$Contributing Back$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A team wants to publish a reusable component it built during a client engagement. What must be checked first?$q$, $q$Accelerators & IP Contribution$q$, $q$Contributing Back$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A team is about to build a Claude-based feature. Which question belongs in requirements gathering?$q$, $q$Accelerators & IP Contribution$q$, $q$Requirements & Lifecycle$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$A security team requires Claude usage to stay inside the company's existing cloud provider account and governance. What should the team compare?$q$, $q$Accelerators & IP Contribution$q$, $q$Comparing Platforms$q$),
  ($q$developer$q$, $q$Applications and Integration$q$, $q$An integration runs on one platform today and may need to move to another later. Which design choice makes a move easiest?$q$, $q$Accelerators & IP Contribution$q$, $q$Comparing Platforms$q$)
)
update quiz_questions qq
set submodule_id = sm.id, topic_id = t.id
from nq
join quiz_modules m on m.title = nq.domain and m.track = nq.track
join quiz_submodules sm on sm.module_id = m.id and sm.title = nq.course
join quiz_skilljar_topics t on t.submodule_id = sm.id and t.lesson_title = nq.lesson
where qq.module_id = m.id and qq.question = nq.question and qq.submodule_id is null;

-- 3. Lesson memberships: the questions already mapped to a lesson, the existing ones that also fit another lesson, and the new ones
--    (172 in all). Each points at the first row of its lesson; the app groups a lesson across domains by its name.
with mem(track, domain, question, course, lesson) as (values
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A support team needs thousands of short, routine reply drafts per day, where speed and cost matter most. Which approach fits best?$q$, $q$Claude Platform & Model Foundations$q$, $q$Choosing Models$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Which statement best describes how the Claude model tiers are generally positioned?$q$, $q$Claude Platform & Model Foundations$q$, $q$Choosing Models$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A legal team needs Claude to analyse a complex contract for subtle conflicts between clauses. Quality matters far more than speed. Which choice fits best?$q$, $q$Claude Platform & Model Foundations$q$, $q$Choosing Models$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A long conversation with Claude has drifted and earlier instructions seem to be ignored. What is the most sensible action?$q$, $q$Claude Platform & Model Foundations$q$, $q$Context Management$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$Which practices help when a long conversation approaches its context limit? Select 2.$q$, $q$Claude Platform & Model Foundations$q$, $q$Context Management$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A consultant needs to produce a polished, shareable interactive dashboard from a data summary and iterate on its layout. Which Claude capability is the best fit?$q$, $q$Claude Platform & Model Foundations$q$, $q$Capability Layer$q$),
  ($q$associate$q$, $q$Product and Model Selection$q$, $q$A team wants every member's chats about one client to share the same background documents and instructions. Which feature fits best?$q$, $q$Claude Platform & Model Foundations$q$, $q$Capability Layer$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$A marketing coordinator types "Write something about our new product." The first draft is generic. Which change would most improve the next result?$q$, $q$Prompting & Task Execution$q$, $q$Anatomy of an Effective Prompt$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$A recruiter wants Claude to screen candidate summaries. Which prompt is most likely to produce consistent, usable results?$q$, $q$Prompting & Task Execution$q$, $q$Anatomy of an Effective Prompt$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$An operations lead wants Claude to turn 40 pages of meeting notes into a risk register, a stakeholder email and a one-page summary. What is the best approach?$q$, $q$Prompting & Task Execution$q$, $q$Task Decomposition$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$A finance analyst wants a quarterly variance commentary built from four data exports. Which approach gives the most reliable result?$q$, $q$Prompting & Task Execution$q$, $q$Task Decomposition$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$Claude's first draft of a client update is accurate but far too formal. What is the most effective next step?$q$, $q$Prompting & Task Execution$q$, $q$Iterating to Improve Output$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$Which actions are good ways to improve a prompt that gives inconsistent output? Select 2.$q$, $q$Prompting & Task Execution$q$, $q$Iterating to Improve Output$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$A strategy analyst needs Claude to brainstorm 15 possible market-entry ideas, then later compare three of them rigorously. How should the prompting differ between the two tasks?$q$, $q$Prompting & Task Execution$q$, $q$Adapting Strategy by Task Type$q$),
  ($q$associate$q$, $q$Prompting and Task Execution$q$, $q$A team wants Claude to draft a customer email and also to analyse survey data for trends. How should the prompts differ?$q$, $q$Prompting & Task Execution$q$, $q$Adapting Strategy by Task Type$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$You asked Claude to summarise a contract's termination, payment and liability clauses. The summary covers termination and payment only. What does this show?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Discernment: Accuracy & Completeness$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$You asked Claude for a comparison of three vendors across price, support and security. The response covers price and support only. What should you do?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Discernment: Accuracy & Completeness$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Which of these are common warning signs that a Claude response may contain a hallucination? Select 2.$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Hallucinations, Inconsistencies & Bias$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Claude's summary of a court case includes a quote attributed to a named judge. You cannot find the quote in the case documents you supplied. What is the right conclusion?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Hallucinations, Inconsistencies & Bias$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Claude is asked to rank candidate job titles by seniority and consistently puts titles associated with one gender lower. What should the team do?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Hallucinations, Inconsistencies & Bias$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Claude summarises a market report and states that a competitor's revenue grew 38% last year. The figure will go into a board deck. What should you do first?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Fact-Checking & Grounding$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Which checks are appropriate before sharing a Claude-generated market analysis with a client? Select 2.$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Fact-Checking & Grounding$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$A team uses Claude to draft responses to customer complaints. Which situation most clearly requires a human to review before sending?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Diligence: When Review Is Non-Negotiable$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Which Claude output most clearly requires human expert review before use?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Diligence: When Review Is Non-Negotiable$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Claude wrote a technical incident summary. You need to send it to non-technical executives. What is the best approach?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Editing & Adapting for Audience$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$Claude produced a detailed technical proposal. The audience is a busy executive who will read for two minutes. What is the best next step?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Editing & Adapting for Audience$q$),
  ($q$associate$q$, $q$Output Evaluation and Validation$q$, $q$A finance analyst wants Claude's output to be pasted into a spreadsheet with consistent columns. Which output request works best?$q$, $q$Evaluating & Validating Claude's Output$q$, $q$Choosing Output Formats$q$),
