insert into quiz_lesson_questions (topic_id, question_id)
select (select min(t.id) from quiz_skilljar_topics t where t.course_title = mem.course and t.lesson_title = mem.lesson), qq.id
from mem
join quiz_modules m on m.title = mem.domain and m.track = mem.track
join quiz_questions qq on qq.module_id = m.id and qq.question = mem.question
where not exists (select 1 from quiz_lesson_questions)
on conflict (topic_id, question_id) do nothing;

-- Check: questions per course and lesson. A lesson with 0 cannot appear in a module quiz.
select t.course_title as course, t.lesson_title as lesson, count(lq.id) as questions
from quiz_skilljar_topics t
left join quiz_lesson_questions lq on lq.topic_id = t.id
where t.lesson_title is not null and t.id = (select min(t2.id) from quiz_skilljar_topics t2 where t2.course_title = t.course_title and t2.lesson_title = t.lesson_title)
group by t.course_title, t.lesson_title
order by t.course_title, min(t.order_index), t.lesson_title;
